flasks = {'A': 0, 'B': 0, 'C': 0}
max_volume = {'A': 5, 'B': 3, 'C': 12}
a, b, c = "ABC"


# Наполнить
def fill(n):
    flasks[n] = max_volume[n]


# Вылить
def pour_out(n):
    flasks[n] = 0


# Перелить из a в b
def pour_over(a, b):
    if flasks[b] + flasks[a] <= max_volume[b]:
        flasks[b] += flasks[a]
        flasks[a] = 0
    else:
        volume = max_volume[b] - flasks[b]
        flasks[b] = max_volume[b]
        flasks[a] -= volume


for _ in range(15):
    fill(a)
    pour_over(a, b)
    pour_over(a, c)
    pour_out(b)
    pour_over(c, b)

print(flasks[c])
